def enc(v):return(json.dumps(v,sort_keys=True,indent=2,allow_nan=False)+'\n').encode()
def pin(b):return dict(bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
def apply(target,case):
 if case!='normal':raise ValueError('capacity internal normal case only')
 target=Path(target);raw=(target/'upgrade-config.json').read_bytes();cfg=json.loads(raw)
 for name,edits in EDITS:
  body=(target/name).read_bytes();assert cfg['code_pins'][name]==pin(body)['sha256'];text=body.decode()
  for old,new in edits:assert text.count(old)==1;text=text.replace(old,new,1)
  restored=text
  for old,new in reversed(edits):assert restored.count(new)==1;restored=restored.replace(new,old,1)
  assert restored.encode()==body;(target/name).write_text(text);cfg['code_pins'][name]=pin(text.encode())['sha256']
 for name,body in EXTRA.items():(target/name).write_bytes(body);cfg['code_pins'][name]=pin(body)['sha256']
 cfg.update(copy_seconds=BUDGETS['copy'],stage_seconds=BUDGETS['source_stage'],verify_seconds=BUDGETS['source_verify'],driver_seconds=BUDGETS['driver']);(target/'upgrade-config.json').write_bytes(enc(cfg))
 receipt=json.loads((target/'adapter.json').read_bytes());receipt['config_sha256']=pin(enc(cfg))['sha256'];receipt['capacity_context']=dict(purpose='generic16k-fullcopy-capacity',profile_sha256=PROFILE_SHA256,budgets=BUDGETS,production_config=pin(raw),actual=None,acceptance=False);(target/'adapter.json').write_bytes(enc(receipt))
